import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.WFmvnizL.js";const k=JSON.parse('{"title":"How to Enable TSDB","description":"Enable Nezha built-in TSDB with the correct data-path environment variable, retention and resource settings, effective-state verification, and legacy-history migration limits.","frontmatter":{"description":"Enable Nezha built-in TSDB with the correct data-path environment variable, retention and resource settings, effective-state verification, and legacy-history migration limits.","outline":"deep"},"headers":[],"relativePath":"en_US/guide/q15.md","filePath":"en_US/guide/q15.md","lastUpdated":1792850916000}'),n={name:"en_US/guide/q15.md"};function o(r,e,d,l,h,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="how-to-enable-tsdb" tabindex="-1">How to Enable TSDB <a class="header-anchor" href="#how-to-enable-tsdb" aria-label="Permalink to &quot;How to Enable TSDB&quot;">​</a></h1><p>TSDB is disabled by default. The Dashboard initializes the built-in VictoriaMetrics storage only when <code>tsdb.data_path</code> is configured.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>After TSDB is enabled, the server detail page can query historical metric periods such as 1 day, 7 days, and 30 days. When TSDB is disabled, the frontend locks these historical periods.</p><p>Service monitoring history still reads from the database when TSDB is disabled. After TSDB is enabled, it reads from TSDB instead.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Edit the Dashboard configuration file, usually <code>/opt/nezha/dashboard/data/config.yaml</code>, and add or update:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tsdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  data_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/tsdb&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  retention_days</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  min_free_disk_space_gb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_memory_mb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">256</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  write_buffer_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">512</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  write_buffer_flush_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><p><code>data_path</code> can be relative or absolute. Relative paths are resolved from the Dashboard working directory. If this field is empty, TSDB is not enabled.</p><p>You can also enable it with an environment variable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NZ_TSDB_DATAPATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">data/tsdb</span></span></code></pre></div><p>Restart the Dashboard after changing the configuration.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Check the Dashboard log after restart:</p><ul><li><code>TSDB initialized successfully</code>: TSDB is enabled.</li><li><code>TSDB is disabled (tsdb.data_path not configured)</code>: <code>data_path</code> is not configured, so TSDB is still disabled.</li></ul><p>The frontend also reads <code>tsdb_enabled</code> from the system configuration API. If it is <code>false</code>, historical metric periods on the server detail page stay locked.</p><h2 id="low-disk-space" tabindex="-1">Low Disk Space <a class="header-anchor" href="#low-disk-space" aria-label="Permalink to &quot;Low Disk Space&quot;">​</a></h2><p>Dashboard handles low disk space with graceful degradation:</p><ul><li>If storage becomes read-only below <code>min_free_disk_space_gb</code>, new metric writes are paused and discarded while existing history remains queryable. Writes resume automatically once space recovers and storage leaves read-only mode.</li><li>A disk-full or quota-exhaustion error during writing or flushing pauses writes until Dashboard restarts. Free disk space before restarting.</li><li>If disk exhaustion prevents TSDB initialization at startup, Dashboard keeps running and attempts to prepare SQLite service-history storage. TSDB is disabled for that process and <code>tsdb_enabled</code> is <code>false</code>. Free space and restart to reopen TSDB.</li></ul><p>Look for <code>TSDB writes paused</code>, <code>TSDB writes resumed</code>, and <code>TSDB disk is full</code> in logs to distinguish these cases. Samples discarded during a pause are not queued for backfill, so charts may have gaps. Degradation does not migrate existing TSDB history back to SQLite, and it does not guarantee SQLite can still write when it shares the full disk.</p><p><a href="/en_US/guide/servers.html#online-history">Server online history</a> uses separate database session records. It does not require TSDB and is not governed by TSDB metric retention.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>After TSDB is enabled, the Dashboard drops the legacy <code>service_histories</code> database table. Existing service monitoring history is not automatically migrated to TSDB, so back up the database before enabling it.</p><p>TSDB uses local disk storage. Make sure the partition for <code>data_path</code> has enough free space, and adjust <code>retention_days</code>, <code>min_free_disk_space_gb</code>, and <code>max_memory_mb</code> according to your server count and retention needs.</p>`,24)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
